import org.springframework.web.servlet.ModelAndView;

class LoggingOverviewControllerTest {

	@Test
	void zeroCountUsesTheDefaultPageSize() throws Exception {
		assertPageSize("0", 50);
	}

	@Test
	void invalidAndNegativeCountsUseTheDefaultPageSize() throws Exception {
		assertPageSize("-1", 50);
		assertPageSize("not-a-number", 50);
		assertPageSize("2147483648", 50);
		assertPageSize(null, 50);
	}

	@Test
	void oversizedCountsStopAtTheLargestOfferedPageSize() throws Exception {
		assertPageSize("501", 500);
		assertPageSize(Integer.toString(Integer.MAX_VALUE), 500);
	}

	@Test
	void positiveCountsWithinThePageMaximumRemainValid() throws Exception {
		for (int count : new int[] { 1, 50, 100, 200, 500 }) {
			assertPageSize(Integer.toString(count), count);
		}
	}

	private static void assertPageSize(String requestedCount, int expectedCount) throws Exception {
		AppConfiguration appConfiguration = mock(AppConfiguration.class);
		LogConfiguration logConfiguration = mock(LogConfiguration.class);
		LogReader logReader = mock(LogReader.class);
		when(appConfiguration.getLogConfiguration()).thenReturn(logConfiguration);
		when(logConfiguration.getDefaultLogReader()).thenReturn(logReader);

		LoggingOverviewController controller = new LoggingOverviewController();
		controller.setConfig(appConfiguration);
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/system/logging/overview.view");
		if (requestedCount != null) {
			request.addParameter("count", requestedCount);
		}
		ModelAndView result = controller.handleRequest(request, new MockHttpServletResponse());

		assertThat(result.getModel()).containsEntry("count", expectedCount);
		verify(logReader).setLimit(expectedCount);
	}
}
